  float entry=-1e30; float leave=1e30; int entryAxis=0;
  for (int a=0;a<3;a++) {
    if (gridDirection[a]==0.0) {
      if (o[a]<0.0 || o[a]>=float(gridSize[a])) { return h; }
    } else {
      float t0=(0.0-o[a])/gridDirection[a]; float t1=(float(gridSize[a])-o[a])/gridDirection[a];
